import heapq


def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    domains = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        domains.append([-1] + versions)

    best_vector = None
    best_versions = None
    for choices in product(*domains):
        selected = dict(zip(names, choices))
        installed = {name for name, version in selected.items() if version != -1}

        if any(name not in installed or not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        edges = {name: [] for name in installed}
        valid = True
        for name in installed:
            row = next((r for r in packages[name] if r["version"] == selected[name]), None)
            if row is None:
                valid = False
                break
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = selected.get(target, -1)
                if version == -1 or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if reachable != installed:
            continue

        finished, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in installed):
            continue

        vector = tuple(selected[name] for name in names)
        if best_vector is None or (vector > best_vector if preference == "maximum"
                                   else vector < best_vector):
            best_vector = vector
            best_versions = {name: selected[name] for name in installed}

    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


def _build_dependency_solver(preference, name_order):
    return lambda data: _dependency_solver(data, preference, name_order)


def _rounded(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator * 2 + denominator) // (2 * denominator)
    return numerator // denominator


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _rounded(raw * (10000 - discount), 10000, mode)
        tax = _rounded(net * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    available = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in available}):
        return {"error": "impossible"}

    best_value = None
    best_ids = None
    quotas = data.get("quotas", {})
    for subset in combinations(available, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active_ends = []
        compatible = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"], row["id"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                compatible = False
                break
        if not compatible:
            continue
        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    full_mask = (1 << len(required)) - 1
    required_bit = {}
    for i, node in enumerate(required):
        required_bit[node] = 1 << i

    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = required_bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full_mask:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                discounted = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((discounted, coupons - 1))
            next_node = edge["v"]
            next_mask = mask | required_bit.get(next_node, 0)
            for duration, next_coupons in options:
                next_arrival = depart + duration
                if next_arrival > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, next_coupons)
                if next_arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = next_arrival
                    heapq.heappush(queue, (next_arrival, next_node, next_mask, next_coupons))
    return {"arrival": None}


